class ModelFormMetaclassNewTests(TestCase):
    def test_inherit_formfield_callback_from_parent(self):
        """Path 1: Base class has Meta.formfield_callback and bases == (BaseModelForm,)."""
        callback = lambda f, **kwargs: None

        class ParentForm(forms.ModelForm):
            class Meta:
                model = Author
                fields = ['name']
                formfield_callback = callback

        # Creating a child form with bases == (BaseModelForm,)
        class ChildForm(ParentForm):
            pass

        self.assertEqual(ChildForm._meta.formfield_callback, callback)

    def test_inherit_from_multiple_bases_with_callback_in_second(self):
        """Path 2: First base no Meta, second has Meta.formfield_callback and bases == (BaseModelForm,)."""
        callback = lambda f, **kwargs: None

        class BaseNoMeta(forms.ModelForm):
            pass

        class ParentWithCallback(forms.ModelForm):
            class Meta:
                model = Author
                fields = ['name']
                formfield_callback = callback

        # Create a new class inheriting from both
        class ChildForm(BaseNoMeta, ParentWithCallback):
            pass

        self.assertEqual(ChildForm._meta.formfield_callback, callback)

    def test_no_callback_in_bases_use_attrs(self):
        """Path 3 and 4: No base has callback, formfield_callback set via attrs."""
        callback = lambda f, **kwargs: None

        # Test case where bases == (BaseModelForm,)
        class TestForm1(forms.ModelForm):
            formfield_callback = callback

            class Meta:
                model = Author
                fields = ['name']

        self.assertEqual(TestForm1._meta.formfield_callback, callback)

        # Test case where bases != (BaseModelForm,)
        class Mixin:
            pass

        class TestForm2(Mixin, forms.ModelForm):
            formfield_callback = callback

            class Meta:
                model = Author
                fields = ['name']

        self.assertEqual(TestForm2._meta.formfield_callback, callback)

    def test_no_callback_or_attrs_no_base_model_form(self):
        """Path 3: No callback in bases or attrs, bases != (BaseModelForm,)."""
