            pass

        class TestForm(CustomBase, metaclass=forms.ModelFormMetaclass):
            class Meta:
                model = Author
                fields = ['name']

        self.assertFalse(hasattr(TestForm._meta, 'formfield_callback'))

    def test_no_callback_in_bases_defaults_to_none(self):
        """Path 4 and 5: No callback in bases, bases == (BaseModelForm,)."""
        class TestForm(forms.ModelForm):
            class Meta:
                model = Author
                fields = ['name']

        self.assertFalse(hasattr(TestForm._meta, 'formfield_callback'))
