def test_alt_spellings_catch_all(testdir):
    """Test that each alternative spelling of parametrize raises a specific error."""
    for alt in ["parameterize", "parametrise", "parameterise"]:
        testdir.makepyfile(
            test_alt="""
            import pytest

            @pytest.{alt}(('arg', [1, 2]))
            def test_func(arg):
                pass
        """.format(alt=alt)
        )
        result = testdir.runpytest()
        result.stdout.fnmatch_lines([
            "*test_func has '{alt}' mark, spelling should be 'parametrize'".format(alt=alt)
        ])
        assert result.ret != 0
